function autoSelectSingleChoice(params) {
    const questionName = params[0];
    const question = this.survey.getQuestionByName(questionName);

    if (!question) {
        return "";
    }

    const choices = question.choices || [];

    if (choices.length === 1) {
        question.value = choices[0].value;
        return choices[0].value;
    }

    return question.value || "";
}
